/* Stack18 mega-menu behaviour. Generated by build_nav.py. */
(function () {
  document.documentElement.classList.add('js');
  var items = Array.prototype.slice.call(document.querySelectorAll('.mm-item'));
  if (!items.length) return;
  var hoverable = window.matchMedia && window.matchMedia('(hover:hover)').matches;

  function trig(it) { return it.querySelector('.mm-trigger'); }
  function set(it, open) {
    it.classList.toggle('is-open', open);
    trig(it).setAttribute('aria-expanded', open ? 'true' : 'false');
  }
  function closeAll(except) {
    items.forEach(function (it) { if (it !== except) set(it, false); });
  }

  items.forEach(function (it) {
    var t = trig(it);
    t.addEventListener('click', function () {
      var open = !it.classList.contains('is-open');
      closeAll(it);
      set(it, open);
    });
    if (hoverable) {
      /* Hover intent: a menu opens only once the cursor rests on it, and closes after a short grace
         period, so sweeping across a neighbouring button on the way to the panel does nothing. */
      it.addEventListener('mouseenter', function () {
        clearTimeout(it._ct);
        items.forEach(function (o) { if (o !== it) clearTimeout(o._ot); });
        if (it.classList.contains('is-open')) return;
        var anyOpen = items.some(function (o) { return o.classList.contains('is-open'); });
        it._ot = setTimeout(function () { closeAll(it); set(it, true); }, anyOpen ? 320 : 70);
      });
      it.addEventListener('mouseleave', function () {
        clearTimeout(it._ot);
        it._ct = setTimeout(function () { set(it, false); }, 260);
      });
    }
    it.addEventListener('focusout', function (e) {
      if (!e.relatedTarget || !it.contains(e.relatedTarget)) set(it, false);
    });
  });

  document.addEventListener('click', function (e) {
    if (!e.target.closest('.mm-item')) closeAll();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    var open = items.filter(function (it) { return it.classList.contains('is-open'); })[0];
    if (open) { set(open, false); trig(open).focus(); }
  });
  window.addEventListener('resize', function () { if (window.innerWidth < 1024) closeAll(); });
})();

/* Split panels: switch the pane from the group rail */
(function () {
  Array.prototype.slice.call(document.querySelectorAll('.mm-split')).forEach(function (root) {
    var tabs = Array.prototype.slice.call(root.querySelectorAll('.mm-tab'));
    var panes = Array.prototype.slice.call(root.querySelectorAll('.mm-pane'));
    function on(i, focus) {
      tabs.forEach(function (t, j) {
        var a = j === i;
        t.classList.toggle('is-on', a);
        t.setAttribute('aria-selected', a ? 'true' : 'false');
        t.tabIndex = a ? 0 : -1;
        panes[j].classList.toggle('is-on', a);
      });
      if (focus) tabs[i].focus();
    }
    tabs.forEach(function (t, i) {
      t.addEventListener('mouseenter', function () { on(i); });
      t.addEventListener('click', function () { on(i); });
      t.addEventListener('focus', function () { on(i); });
      t.addEventListener('keydown', function (e) {
        if (e.key === 'ArrowDown' || e.key === 'ArrowRight') { e.preventDefault(); on((i + 1) % tabs.length, true); }
        else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') { e.preventDefault(); on((i - 1 + tabs.length) % tabs.length, true); }
      });
    });
  });
})();

/* Footer accordions: always open on desktop, collapsible on mobile */
(function () {
  var cols = Array.prototype.slice.call(document.querySelectorAll('.sf-col'));
  if (!cols.length || !window.matchMedia) return;
  var mq = window.matchMedia('(max-width:719px)');
  function sync() { cols.forEach(function (d) { d.open = !mq.matches; }); }
  cols.forEach(function (d) {
    d.querySelector('summary').addEventListener('click', function (e) { if (!mq.matches) e.preventDefault(); });
  });
  sync();
  if (mq.addEventListener) mq.addEventListener('change', sync); else mq.addListener(sync);
})();
